R,C=len(G),len(G[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if G[r][c]==0 and (r,c) not in seen:
   q=[(r,c)]; seen.add((r,c)); cells=[]
   while q:
    x,y=q.pop(); cells.append((x,y))
    for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
     a,b=x+dx,y+dy
     if 0<=a<R and 0<=b<C and G[a][b]==0 and (a,b) not in seen: seen.add((a,b));q.append((a,b))
   comps.append((len(cells), any(x==0 or x==R-1 or y==0 or y==C-1 for x,y in cells), sorted(cells)))
for comp in comps: print(comp)

